import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

/**
 * @param {any} config
 * @param {any} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Vector3 } = ctx.THREE;

  // Root container – the adapter will set position/rotation/scale later.
  const root = new Group();

  // Geometry for the badge (unit square, can be scaled by parent).
  const geometry = new PlaneGeometry(1, 1);
  const material = new MeshBasicNodeMaterial({ transparent: true });

  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Load texture asynchronously; apply when ready.
  let texture = null;
  if (config.imageUrl) {
    ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((tex) => {
        texture = tex;
        material.map = tex;
        material.needsUpdate = true;
      })
      .catch(() => {
        // texture loading failure – keep material empty.
      });
  }

  // Store original Y to calculate hover lift.
  const originalY = 0;
  const hoverOffset = 0.15;

  // GSAP timelines (will be created on demand).
  let hoverUpTimeline = null;
  let hoverDownTimeline = null;
  const cleanup = [];

  // ---------- Interaction Handlers ----------
  const handlers = {};

  // Hover enter – lift badge.
  handlers.hoverEnter = () => {
    if (hoverUpTimeline) hoverUpTimeline.kill();
    if (hoverDownTimeline) hoverDownTimeline.kill();

    hoverUpTimeline = gsap.timeline({ onComplete: () => (hoverUpTimeline = null) });
    hoverUpTimeline.to(
      mesh.position,
      {
        y: originalY + hoverOffset,
        duration: 0.4,
        ease: 'power3.out',
      },
    );
    cleanup.push(() => hoverUpTimeline && hoverUpTimeline.kill());
  };

  // Hover leave – return to original position.
  handlers.hoverLeave = () => {
    if (hoverUpTimeline) hoverUpTimeline.kill();
    if (hoverDownTimeline) hoverDownTimeline.kill();

    hoverDownTimeline = gsap.timeline({ onComplete: () => (hoverDownTimeline = null) });
    hoverDownTimeline.to(
      mesh.position,
      {
        y: originalY,
        duration: 0.3,
        ease: 'power2.out',
      },
    );
    cleanup.push(() => hoverDownTimeline && hoverDownTimeline.kill());
  };

  // Click – emit navigation event and press‑down feedback.
  handlers.click = () => {
    // Press‑down feedback.
    const pressTimeline = gsap.timeline({ onComplete: () => pressTimeline.kill() });
    pressTimeline
      .to(mesh.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(1.7)' })
      .to(mesh.scale, { x: 1, y: 1, z: 1, duration: 0.12, ease: 'back.out(1.7)' });
    cleanup.push(() => pressTimeline.kill());

    // Emit event for navigation.
    ctx.emit('hub-collection.select', {});
  };

  // Expose handlers via userData.
  root.userData.handlers = handlers;

  // Store data binding information (no runtime fetching).
  root.userData.binding = {
    source: 'trpc.journal.posts.posts[]',
    target: 'rows[]',
  };

  // Cleanup routine.
  root.userData.cleanup = () => {
    // Dispose geometry and material.
    geometry.dispose();
    material.dispose();
    if (texture && texture.dispose) {
      texture.dispose();
    }
    // Kill any GSAP timelines.
    cleanup.forEach((fn) => {
      try {
        fn();
      } catch (e) {
        // ignore
      }
    });
  };

  // Return the prepared object.
  return root;
}
